export function regionalLocalities([s,w,n,e]){
  if(s<20||w< -100.5||n>20.7||e> -99.8)return null;
  const results=places.filter(p=>p[1]>=s&&p[1]<=n&&p[2]>=w&&p[2]<=e);
  if(results.length>1000)return null;
  return results.map(([name,lat,lon])=>({name,lat,lon}));
}
